function closeDetail() {
  selectedCard = null;
  document.getElementById('detail-panel').classList.remove('show');
  renderFleet();
}

function filterFleet(f, btn) {
  currentFilter = f;
  document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  closeDetail();
}

function switchTab(tab) {
  document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
  event.target.classList.add('active');
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.getElementById('page-' + tab).classList.add('active');
  if (tab === 'revenus') renderRevenue();
  if (tab === 'chauffeurs') renderDrivers();
}

function renderRevenue() {
  const maxRev = Math.max(...vehicles.map(v => v.revenue));
  document.getElementById('rev-chart').innerHTML = vehicles.map(v => `
    <div class="rev-bar-wrap">
      <div style="font-size:11px;color:var(--color-text-secondary);margin-bottom:2px;">${v.revenue > 0 ? v.revenue+'€' : ''}</div>
      <div class="rev-bar" style="height:${maxRev > 0 ? Math.round(v.revenue / maxRev * 80) : 0}px;background:${v.revenue > 0 ? '#EF9F27' : 'var(--color-background-secondary)'}"></div>
      <div class="rev-label">${v.id}</div>
    </div>
  `).join('');
  const total = vehicles.reduce((s,v) => s+v.revenue, 0);
  document.getElementById('rev-list').innerHTML = vehicles.filter(v=>v.revenue>0).sort((a,b)=>b.revenue-a.revenue).map(v => `
    <div style="background:var(--color-background-primary);border:0.5px solid var(--color-border-tertiary);border-radius:var(--border-radius-lg);padding:12px 16px;display:flex;align-items:center;justify-content:space-between;">
      <div>
        <div style="font-weight:500;font-size:14px;">${v.id} — ${v.driver}</div>
        <div style="font-size:12px;color:var(--color-text-secondary);">${v.courses} courses</div>
      </div>
      <div style="font-size:16px;font-weight:500;color:#3B6D11;">${v.revenue} €</div>
    </div>
  `).join('') + `
    <div style="background:var(--color-background-secondary);border-radius:var(--border-radius-lg);padding:12px 16px;display:flex;justify-content:space-between;align-items:center;grid-column:1/-1;">
      <div style="font-size:14px;font-weight:500;">Total journalier</div>
      <div style="font-size:18px;font-weight:500;">${total} €</div>
    </div>`;
}

function renderDrivers() {
  document.getElementById('drivers-grid').innerHTML = vehicles.map(v => `
    <div style="background:var(--color-background-primary);border:0.5px solid var(--color-border-tertiary);border-radius:var(--border-radius-lg);padding:16px;">
      <div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;">
        <div class="avatar" style="width:40px;height:40px;font-size:14px;">${v.driver.split(' ').map(n=>n[0]).join('')}</div>
        <div>
          <div style="font-weight:500;font-size:14px;">${v.driver}</div>
          <div style="font-size:12px;color:var(--color-text-secondary);">${v.id} · ${v.plate}</div>
        </div>
      </div>
      <span class="status-badge status-${v.status}" style="margin-bottom:10px;display:inline-block;">${statusLabel(v.status)}</span>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px;">
        <div><div style="font-size:11px;color:var(--color-text-secondary);">Courses</div><div style="font-weight:500;">${v.courses}</div></div>
        <div><div style="font-size:11px;color:var(--color-text-secondary);">Revenus</div><div style="font-weight:500;">${v.revenue} €</div></div>
        <div><div style="font-size:11px;color:var(--color-text-secondary);">Kilométrage</div><div style="font-weight:500;">${v.km.toLocaleString()} km</div></div>
        <div><div style="font-size:11px;color:var(--color-text-secondary);">Carburant</div><div style="font-weight:500;">${v.fuel}%</div></div>
      </div>
    </div>
  `).join('');
}

renderFleet();
</script>

