import { UserRole } from "../types/auth";

export const authRouter = Router();

authRouter.post("/register-client", async (req, res) => {
  const { fullName, email, phone, password } = req.body as {
    fullName?: string;
    email?: string;
    phone?: string;
    password?: string;
  };

  if (!fullName || !email || !phone || !password) {
    return res.status(400).json({ error: "fullName, email, phone, password are required" });
  }

  const existing = await pg.query("SELECT id FROM users WHERE email = $1", [email]);
  if (existing.rowCount) {
    return res.status(409).json({ error: "Email already in use" });
  }

  const hash = await bcrypt.hash(password, 10);
  const role: UserRole = "client";

  const inserted = await pg.query(
    `INSERT INTO users (full_name, email, phone, password_hash, role)
     VALUES ($1, $2, $3, $4, $5)
     RETURNING id, full_name, email, role`,
    [fullName, email, phone, hash, role]
  );

  return res.status(201).json({ user: inserted.rows[0] });
});

authRouter.post("/login", async (req, res) => {
  const { email, password } = req.body as { email?: string; password?: string };
  if (!email || !password) {
    return res.status(400).json({ error: "email and password are required" });
  }

  const result = await pg.query(
    "SELECT id, email, password_hash, role FROM users WHERE email = $1",
    [email]
  );
  if (!result.rowCount) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  const user = result.rows[0] as {
    id: string;
    email: string;
    password_hash: string;
    role: UserRole;
  };

  const ok = await bcrypt.compare(password, user.password_hash);
  if (!ok) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  const payload = { sub: user.id, role: user.role, email: user.email };
  const accessToken = signAccessToken(payload);
  const refreshToken = signRefreshToken(payload);

  await redis.set(`refresh:${user.id}`, refreshToken, "EX", 60 * 60 * 24 * 7);

  return res.json({ accessToken, refreshToken });
});

authRouter.post("/refresh", async (req, res) => {
  const { refreshToken } = req.body as { refreshToken?: string };
  if (!refreshToken) {
    return res.status(400).json({ error: "refreshToken is required" });
  }

  try {
    const payload = verifyRefreshToken(refreshToken);
    const stored = await redis.get(`refresh:${payload.sub}`);
    if (!stored || stored !== refreshToken) {
      return res.status(401).json({ error: "Invalid refresh token" });
    }
    const accessToken = signAccessToken(payload);
    return res.json({ accessToken });
  } catch {
    return res.status(401).json({ error: "Invalid refresh token" });
  }
});
'@;

