import { Router } from "express";
import { pg } from "../db/postgres";
import { requireAuth, requireRole } from "../middlewares/auth";

export const ridesRouter = Router();

ridesRouter.use(requireAuth);

ridesRouter.post("/", requireRole("client"), async (req, res) => {
  const {
    pickupAddress,
    dropoffAddress,
    pickupLat,
    pickupLng,
    dropoffLat,
    dropoffLng,
    scheduledFor
  } = req.body as {
    pickupAddress?: string;
    dropoffAddress?: string;
    pickupLat?: number;
    pickupLng?: number;
    dropoffLat?: number;
    dropoffLng?: number;
    scheduledFor?: string | null;
  };

  if (!pickupAddress || !dropoffAddress || pickupLat == null || pickupLng == null || dropoffLat == null || dropoffLng == null) {
    return res.status(400).json({ error: "Pickup/dropoff fields are required" });
  }

  const status = scheduledFor ? "reservee" : "demandee";
  const insert = await pg.query(
    `INSERT INTO rides
      (client_id, pickup_address, dropoff_address, pickup_lat, pickup_lng, dropoff_lat, dropoff_lng, scheduled_for, status)
     VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)
     RETURNING id, client_id, status, created_at`,
